def date_to_ordinal(date):
    year, month, day = date
    def is_leap(y):
        return y % 4 == 0 and (y % 100 != 0 or y % 400 == 0)
    def doy(y, m, d):
        lengths = [31,28,31,30,31,30,31,31,30,31,30,31]
        if is_leap(y):
            lengths[1] = 29
        return sum(lengths[:m-1]) + d
    days_before_year = 365*(year-1) + (year-1)//4 - (year-1)//100 + (year-1)//400
    return days_before_year + doy(year, month, day)

def days_between(date1, date2):
    def is_leap(y):
        return y % 4 == 0 and (y % 100 != 0 or y % 400 == 0)
    def doy(y, m, d):
        lengths = [31,28,31,30,31,30,31,31,30,31,30,31]
        if is_leap(y):
            lengths[1] = 29
        return sum(lengths[:m-1]) + d
    def ordinal(date):
        y, m, d = date
        return 365*(y-1) + (y-1)//4 - (y-1)//100 + (y-1)//400 + doy(y, m, d)
    return ordinal(date2) - ordinal(date1)

def add_days(date, n):
    def is_leap(y):
        return y % 4 == 0 and (y % 100 != 0 or y % 400 == 0)
    def dim(y, m):
        lengths = [31,28,31,30,31,30,31,31,30,31,30,31]
        if m == 2 and is_leap(y):
            return 29
        return lengths[m-1]
    y, m, d = date
    d += n
    while d < 1:
        m -= 1
        if m < 1:
            m = 12
            y -= 1
        d += dim(y, m)
    while d > dim(y, m):
        d -= dim(y, m)
        m += 1
        if m > 12:
            m = 1
            y += 1
    return (y, m, d)

def next_day(date):
    def is_leap(y):
        return y % 4 == 0 and (y % 100 != 0 or y % 400 == 0)
    def dim(y, m):
        lengths = [31,28,31,30,31,30,31,31,30,31,30,31]
        if m == 2 and is_leap(y):
            return 29
        return lengths[m-1]
    y, m, d = date
    if d < dim(y, m):
        return (y, m, d+1)
    m += 1
    if m > 12:
        return (y+1, 1, 1)
    return (y, m, 1)

def previous_day(date):
    def is_leap(y):
        return y % 4 == 0 and (y % 100 != 0 or y % 400 == 0)
    def dim(y, m):
        lengths = [31,28,31,30,31,30,31,31,30,31,30,31]
        if m == 2 and is_leap(y):
            return 29
        return lengths[m-1]
    y, m, d = date
    if d > 1:
        return (y, m, d-1)
    m -= 1
    if m < 1:
        return (y-1, 12, 31)
    return (y, m, dim(y, m))

def is_valid_date(year, month, day):
    if year < 1 or month < 1 or month > 12 or day < 1:
        return False
    lengths = [31,28,31,30,31,30,31,31,30,31,30,31]
    if year % 4 == 0 and (year % 100 != 0 or year % 400 == 0):
        lengths[1] = 29
    return day <= lengths[month-1]

def quarter_of_month(month_index):
    normalized = (month_index - 1) % 12 + 1
    return (normalized - 1)//3 + 1

def quarter_of_date(year, month, day):
    q = (month - 1)//3 + 1
    return (q, (q-1)*3 + 1)

def days_remaining_in_month(year, month, day):
    lengths = [31,28,31,30,31,30,31,31,30,31,30,31]
    if year % 4 == 0 and (year % 100 != 0 or year % 400 == 0):
        lengths[1] = 29
    return lengths[month-1] - day

def days_remaining_in_year(year, month, day):
    lengths = [31,28,31,30,31,30,31,31,30,31,30,31]
    if year % 4 == 0 and (year % 100 != 0 or year % 400 == 0):
        lengths[1] = 29
    doy = sum(lengths[:month-1]) + day
    return sum(lengths) - doy

def is_weekend(year, month, day):
    y, m, d = year, month, day
    if m < 3:
        m += 12
        y -= 1
    k = y % 100
    j = y // 100
    h = (d + (13*(m+1))//5 + k + k//4 + j//4 + 5*j) % 7
    return h in (0, 1)

def minutes_since_midnight(time_str):
    h, m = time_str.split(':')
    return int(h)*60 + int(m)
